/** Typed access to the frozen dataset (generated by scripts/extract-data.mjs). */
import raw from './data.json';
import type { Lang } from './storyboard';

export const DATA = raw;
export type Data = typeof raw;

/** Pick the language variant of a field pair like { titleAr, titleEn }. */
export function L<T extends Record<string, unknown>>(obj: T, key: string, lang: Lang): string {
  const v = obj[`${key}${lang === 'ar' ? 'Ar' : 'En'}`];
  return typeof v === 'string' ? v : '';
}
